using Alterverse.AI;using Alterverse.Characters;using Alterverse.Visuals;using UnityEngine;using UnityEngine.InputSystem;
namespace Alterverse.Combat
{
[RequireComponent(typeof(Health))]public sealed class BasicAttack:MonoBehaviour
{
[SerializeField,Min(.1f)]private float fallbackRange=2.2f;[SerializeField,Min(0f)]private float fallbackDamage=20f;[SerializeField,Min(.05f)]private float fallbackCooldown=.78f;[SerializeField]private LayerMask targetMask=~0;private readonly Collider[] hitBuffer=new Collider[32];private Health selfHealth;private TeamMember selfTeam;private HeroCombatProfile profile;private HeroIdentity identity;private float nextAttackTime;private HeroCombatProfile Profile{get{if(profile==null)profile=GetComponent<HeroCombatProfile>();return profile;}}private float Range=>Profile!=null?Profile.AttackRange:fallbackRange;private float Damage=>Profile!=null?Profile.Attack:fallbackDamage;private float Cooldown=>identity!=null?identity.Hero switch{HeroId.Nyra=>.82f,HeroId.Elyra=>.88f,HeroId.Mira=>.94f,HeroId.Kaelon=>.92f,HeroId.Rook=>.78f,_=>.72f}:fallbackCooldown;
private void Awake(){selfHealth=GetComponent<Health>();selfTeam=GetComponent<TeamMember>();profile=GetComponent<HeroCombatProfile>();identity=GetComponent<HeroIdentity>();}private void Update(){if(Keyboard.current!=null&&Keyboard.current.spaceKey.wasPressedThisFrame)TryAttack();}
public bool TryAttack(){if(selfHealth==null||selfHealth.IsDead||Time.time<nextAttackTime)return false;int count=Physics.OverlapSphereNonAlloc(transform.position,Range,hitBuffer,targetMask,QueryTriggerInteraction.Ignore);Health closest=null;float closestSqr=float.MaxValue;for(int i=0;i<count;i++){Collider hit=hitBuffer[i];if(hit==null)continue;Health h=hit.GetComponentInParent<Health>();if(h==null||h==selfHealth||h.IsDead||!IsEnemy(h))continue;float sqr=(h.transform.position-transform.position).sqrMagnitude;if(sqr<closestSqr){closestSqr=sqr;closest=h;}}if(closest==null)return false;nextAttackTime=Time.time+Cooldown;Color attackColor=HeroColor();PrototypeVfx.Slash(transform,attackColor,Range>4?1.15f:1.5f);Vector3 look=closest.transform.position-transform.position;look.y=0;if(look.sqrMagnitude>.01f)transform.rotation=Quaternion.LookRotation(look.normalized,Vector3.up);closest.TakeDamage(Damage,gameObject);PrototypeVfx.Burst(closest.transform.position,attackColor,.85f,6);return true;}
private Color HeroColor()=>identity!=null?identity.Hero switch{HeroId.Kaelon=>new Color(.12f,.55f,.78f),HeroId.Nyra=>new Color(1f,.62f,.12f),HeroId.Elyra=>new Color(.52f,.2f,.88f),HeroId.Mira=>new Color(.18f,.82f,.38f),HeroId.Rook=>new Color(.72f,.36f,.14f),_=>new Color(.58f,.16f,.90f)}:new Color(.58f,.16f,.90f);private bool IsEnemy(Health h){TeamMember m=h.GetComponent<TeamMember>();if(m!=null&&selfTeam!=null)return m.Team!=selfTeam.Team;LaneMinion minion=h.GetComponent<LaneMinion>();if(minion!=null)return minion.Team!=(selfTeam!=null?selfTeam.Team:0);LaneTower tower=h.GetComponent<LaneTower>();if(tower!=null)return tower.Team!=(selfTeam!=null?selfTeam.Team:0);return h.GetComponent<PrototypeEnemyBot>()!=null;}private void OnDrawGizmosSelected(){Gizmos.DrawWireSphere(transform.position,Application.isPlaying?Range:fallbackRange);}
}
}
